 public static int Main(){string temp=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Verification","Maintenance-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{
  var status=new UpdateFeedback();status.Begin();Check(status.Kind=="checking"&&status.Title.Contains("Checking"),"update check has a distinct checking state");status.Complete(new Version(3,2,0),new Version(3,2,0));Check(status.Kind=="current"&&status.LastChecked.HasValue&&status.Detail.Contains("3.2.0"),"up-to-date result includes versions and check time");status.Complete(new Version(3,1,0),new Version(3,2,0));Check(status.Kind=="available","newer stable release is recognized");status.Complete(new Version(3,2,0),new Version(3,1,0));Check(status.Kind=="ahead"&&!status.Title.Contains("latest"),"unpublished newer build is not called the latest public release");status.Fail("Network unavailable.");Check(status.Kind=="error"&&status.Detail.Contains("try again")&&status.LastChecked.HasValue,"failed update remains a persistent retryable result");
