  var p=Plan(temp);RemovalCore.Validate(p,p.IssuerSID);Check(true,"owned separate removal plan accepted");p=Plan(temp);p.IssuerSID="S-1-5-21-11-22-33-1001";RemovalCore.Validate(p,p.IssuerSID);Check(true,"domain owner and separate local account SIDs need not share a prefix");p=Plan(temp);p.SID=p.IssuerSID;Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"active Windows user cannot be removed");p=Plan(temp);p.SID=p.IssuerSID.Substring(0,p.IssuerSID.LastIndexOf('-'))+"-500";Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"built-in Windows account rejected");p=Plan(temp);p.User="UnrelatedUser";Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"unrelated user name rejected");p=Plan(temp);p.Root=temp;p.Profile=Path.Combine(temp,"Windows Profile");Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"manager-containing root rejected");p=Plan(temp);p.Root=Path.GetDirectoryName(p.MainSteam);p.Profile=Path.Combine(p.Root,"Windows Profile");Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"Main Steam removal overlap rejected");p=Plan(temp);p.Root=Path.GetPathRoot(temp);p.Profile=Path.Combine(p.Root,"Windows Profile");Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"drive root rejected");p=Plan(temp);p.Profile=Path.Combine(temp,"Other Profile");Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"unrecorded profile path rejected");p=Plan(temp);p.Libraries=new[]{Path.Combine(p.Root,"Shared Games")};Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"shared library inside setup rejected");p=Plan(temp);p.Root=Path.Combine(p.Libraries[0],@"steamapps\common\Game");p.Profile=Path.Combine(p.Root,"Windows Profile");Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"shared game folder cannot be removed as setup");p=Plan(temp);p.OriginalProfileBackup=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);Reject(()=>RemovalCore.Validate(p,p.IssuerSID),"active user cannot be a bootstrap backup");
  p=Plan(temp);string users=Path.Combine(temp,"Users"),fallback=Path.Combine(users,p.User),owner=Path.Combine(users,"Owner");RemovalCore.ValidateRegisteredProfile(p,p.Profile,users,owner);Check(true,"original selected profile accepted");Reject(()=>RemovalCore.ValidateRegisteredProfile(p,Path.GetPathRoot(temp),users,owner),"recovered profile cannot be a drive root");RemovalCore.ValidateRegisteredProfile(p,fallback,users,owner);Check(true,"managed SID Windows-default profile accepted");RemovalCore.ValidateRegisteredProfile(p,fallback+".PC.000",users,owner);Check(true,"Windows recreated profile suffix accepted");Reject(()=>RemovalCore.ValidateRegisteredProfile(p,Path.Combine(users,"OtherUser"),users,owner),"another Windows user cannot be recovered as the managed profile");Reject(()=>RemovalCore.ValidateRegisteredProfile(p,Path.Combine(fallback,"Nested"),users,owner),"nested or arbitrary recovery path rejected");Reject(()=>RemovalCore.ValidateRegisteredProfile(p,fallback,users,fallback),"setup owner profile remains protected during recovery");p.Libraries=new[]{fallback};Reject(()=>RemovalCore.ValidateRegisteredProfile(p,fallback,users,owner),"shared game library remains protected during recovery");p=Plan(temp);p.Home=fallback;Reject(()=>RemovalCore.ValidateRegisteredProfile(p,fallback,users,owner),"manager folder remains protected during recovery");p=Plan(temp);Directory.CreateDirectory(users);string recoveryOutside=Path.Combine(temp,"RecoveryOutside");Directory.CreateDirectory(recoveryOutside);using(var command=Process.Start(new ProcessStartInfo(Environment.GetEnvironmentVariable("COMSPEC"),"/c mklink /J \""+fallback+"\" \""+recoveryOutside+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){command.StandardOutput.ReadToEnd();command.StandardError.ReadToEnd();command.WaitForExit();if(command.ExitCode!=0)throw new IOException("Recovery junction fixture could not be created");}Reject(()=>RemovalCore.ValidateRegisteredProfile(p,fallback,users,owner),"linked Windows recovery profile rejected");Directory.Delete(fallback,false);
  string managed=Path.Combine(temp,"delete-only-this"),outside=Path.Combine(temp,"preserve-this"),link=Path.Combine(managed,"linked-library");Directory.CreateDirectory(managed);Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(outside,"proof.txt"),"preserved");string owned=Path.Combine(managed,"readonly.txt");File.WriteAllText(owned,"owned");File.SetAttributes(owned,FileAttributes.ReadOnly);
  using(var command=Process.Start(new ProcessStartInfo(Environment.GetEnvironmentVariable("COMSPEC"),"/c mklink /J \""+link+"\" \""+outside+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){string output=command.StandardOutput.ReadToEnd()+command.StandardError.ReadToEnd();command.WaitForExit();if(command.ExitCode!=0)throw new IOException("Fixture junction could not be created: "+output);}
  Reject(()=>RemovalCore.DeleteTree(link),"linked removal root rejected");RemovalCore.UnlinkProfileLinks(managed);Check(!Directory.Exists(link)&&File.Exists(owned)&&File.ReadAllText(Path.Combine(outside,"proof.txt"))=="preserved","profile link pruning preserves regular files and external targets before Windows profile deletion");RemovalCore.DeleteTree(managed);Check(!Directory.Exists(managed)&&File.ReadAllText(Path.Combine(outside,"proof.txt"))=="preserved","fixture removal deletes read-only files without following shared targets");Reject(()=>RemovalCore.DeleteTree(Path.GetPathRoot(temp)),"deletion refuses drive root");
  string winx=Path.Combine(temp,@"Bootstrap Profile\AppData\Local\Microsoft\Windows\WinX\Group1");Directory.CreateDirectory(winx);File.WriteAllText(Path.Combine(winx,"shortcut.lnk"),"fixture");File.SetAttributes(winx,FileAttributes.Directory|FileAttributes.ReadOnly);File.SetAttributes(Path.GetDirectoryName(winx),FileAttributes.Directory|FileAttributes.ReadOnly);RemovalCore.DeleteTree(Path.Combine(temp,"Bootstrap Profile"));Check(!Directory.Exists(Path.Combine(temp,"Bootstrap Profile")),"WinX Group1 read-only directory and parent are removable");
  string script=Path.Combine(temp,"parse.ps1");File.WriteAllText(script,"param([string]$InputFile)\r\n$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($InputFile,[ref]$t,[ref]$e);if($e.Count){throw ($e|Out-String)}\r\n");Engine.Run(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File "+Engine.Quote(script)+" -InputFile "+Engine.Quote(Path.Combine(Engine.Home,@"Source\Setup-Elevated.ps1")));Check(true,"combined setup/removal script parses in Windows PowerShell 5.1");
  Check(UpdatePackage.Files.Length==20&&!UpdatePackage.Files.Any(f=>f.Contains("Remove-Elevated")),"runtime package remains compatible with the existing updater allowlist");Console.WriteLine(count+" maintenance checks passed.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(Directory.Exists(temp))RemovalCore.DeleteTree(temp);}}
